-- Additive portfolio schema. Existing data is never assigned implicitly.
CREATE TABLE IF NOT EXISTS portfolio_businesses(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,services TEXT NOT NULL,pricing TEXT NOT NULL,audience TEXT NOT NULL,region TEXT NOT NULL,offering_confirmed INTEGER NOT NULL DEFAULT 0,priority INTEGER NOT NULL DEFAULT 3,revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS portfolio_controls(id INTEGER PRIMARY KEY CHECK(id=1),halted INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO portfolio_controls VALUES(1,0);
CREATE TABLE IF NOT EXISTS portfolio_acl(business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),username TEXT NOT NULL REFERENCES office_users(username),can_write INTEGER NOT NULL,PRIMARY KEY(business_id,username));
CREATE TABLE IF NOT EXISTS portfolio_contacts(business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),id TEXT NOT NULL,display_name TEXT NOT NULL,channel_ref TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL,PRIMARY KEY(business_id,id));
CREATE TABLE IF NOT EXISTS portfolio_consents(id INTEGER PRIMARY KEY,business_id TEXT NOT NULL,contact_id TEXT NOT NULL,purpose TEXT NOT NULL,granted INTEGER NOT NULL,notice TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(business_id,contact_id) REFERENCES portfolio_contacts(business_id,id));
CREATE TABLE IF NOT EXISTS portfolio_cases(business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),id TEXT NOT NULL,entry_key TEXT NOT NULL,contact_id TEXT,kind TEXT NOT NULL,subject TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'requested',start_at TEXT,end_at TEXT,created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),UNIQUE(business_id,entry_key),FOREIGN KEY(business_id,contact_id) REFERENCES portfolio_contacts(business_id,id));
CREATE TABLE IF NOT EXISTS portfolio_documents(business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),id TEXT NOT NULL,parent_id TEXT,case_id TEXT,kind TEXT NOT NULL,body TEXT NOT NULL,digest TEXT NOT NULL,business_revision INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'approval_pending',created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),FOREIGN KEY(business_id,case_id) REFERENCES portfolio_cases(business_id,id),FOREIGN KEY(business_id,parent_id) REFERENCES portfolio_documents(business_id,id));
CREATE TABLE IF NOT EXISTS portfolio_operations(business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),id TEXT NOT NULL,entry_key TEXT NOT NULL,kind TEXT NOT NULL,case_id TEXT,document_id TEXT,payload_digest TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'approval_pending',evidence TEXT,created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),UNIQUE(business_id,entry_key),FOREIGN KEY(business_id,case_id) REFERENCES portfolio_cases(business_id,id),FOREIGN KEY(business_id,document_id) REFERENCES portfolio_documents(business_id,id));
CREATE TABLE IF NOT EXISTS portfolio_tasks(business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),task_id TEXT UNIQUE NOT NULL REFERENCES tasks(id),kind TEXT NOT NULL,instruction TEXT NOT NULL,priority INTEGER NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(business_id,task_id));
CREATE TABLE IF NOT EXISTS portfolio_results(business_id TEXT NOT NULL,task_id TEXT NOT NULL,body TEXT NOT NULL,elapsed_seconds REAL,created_at TEXT NOT NULL,PRIMARY KEY(business_id,task_id),FOREIGN KEY(business_id,task_id) REFERENCES portfolio_tasks(business_id,task_id));
CREATE TABLE IF NOT EXISTS portfolio_assignments(id INTEGER PRIMARY KEY,business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),task_id TEXT NOT NULL REFERENCES tasks(id),agent TEXT NOT NULL,reason TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS portfolio_cost_links(cost_id TEXT PRIMARY KEY REFERENCES office_costs(id),business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),task_id TEXT NOT NULL,FOREIGN KEY(business_id,task_id) REFERENCES portfolio_tasks(business_id,task_id));
CREATE TABLE IF NOT EXISTS portfolio_budgets(business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),month TEXT NOT NULL,limit_microusd INTEGER NOT NULL CHECK(limit_microusd>=0),PRIMARY KEY(business_id,month));
CREATE TABLE IF NOT EXISTS portfolio_ledger(business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),id TEXT NOT NULL,entry_key TEXT NOT NULL,day TEXT NOT NULL,kind TEXT NOT NULL,amount_yen INTEGER NOT NULL CHECK(amount_yen>=0),mode TEXT NOT NULL,evidence TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),UNIQUE(business_id,entry_key));
CREATE TABLE IF NOT EXISTS portfolio_measures(business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),id TEXT NOT NULL,day TEXT NOT NULL,metric TEXT NOT NULL,value INTEGER NOT NULL CHECK(value>=0),mode TEXT NOT NULL,evidence TEXT NOT NULL,previous_id TEXT,created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),FOREIGN KEY(business_id,previous_id) REFERENCES portfolio_measures(business_id,id));
CREATE TABLE IF NOT EXISTS portfolio_goals(business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),month TEXT NOT NULL,metric TEXT NOT NULL,value INTEGER CHECK(value>=0),PRIMARY KEY(business_id,month,metric));
CREATE TABLE IF NOT EXISTS portfolio_reports(id TEXT PRIMARY KEY,start_day TEXT NOT NULL,end_day TEXT NOT NULL,body TEXT NOT NULL,digest TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'approval_pending',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS portfolio_events(id INTEGER PRIMARY KEY,business_id TEXT REFERENCES portfolio_businesses(id),actor TEXT NOT NULL,event TEXT NOT NULL,ref TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS portfolio_media(business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),id TEXT NOT NULL,case_id TEXT NOT NULL,stage TEXT NOT NULL,mime TEXT NOT NULL,content BLOB,digest TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'private',created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),FOREIGN KEY(business_id,case_id) REFERENCES portfolio_cases(business_id,id));
CREATE TABLE IF NOT EXISTS portfolio_deletions(business_id TEXT NOT NULL,contact_id TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(business_id,contact_id),FOREIGN KEY(business_id,contact_id) REFERENCES portfolio_contacts(business_id,id));
CREATE TABLE IF NOT EXISTS portfolio_seminar_links(seminar_id TEXT PRIMARY KEY REFERENCES seminars(id),business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),actor TEXT NOT NULL,created_at TEXT NOT NULL);
